-- Impala column comments for customer_360
-- Adjust database name if needed.
USE demo_ai;

ALTER TABLE customer_360 CHANGE customer_id customer_id STRING COMMENT 'Unique synthetic identifier for a customer. Domain: Identifier. Classification: No. Example: CUST000001. Use as the primary customer key.';
ALTER TABLE customer_360 CHANGE customer_type customer_type STRING COMMENT 'Type of customer entity. Domain: Customer Profile. Classification: No. Allowed values: Individual, Organization.';
ALTER TABLE customer_360 CHANGE customer_name customer_name STRING COMMENT 'Synthetic display name of the customer or organization. Domain: Customer Profile. Classification: Yes. Demo data only. Treat as personally identifiable information in real deployments.';
ALTER TABLE customer_360 CHANGE gender gender STRING COMMENT 'Gender of an individual customer. Domain: Customer Profile. Classification: Yes. Typical values: Male, Female. May be NULL for organizations.';
ALTER TABLE customer_360 CHANGE birth_date birth_date DATE COMMENT 'Date of birth for an individual customer. Domain: Customer Profile. Classification: Yes. May be NULL for organizations.';
ALTER TABLE customer_360 CHANGE age age INT COMMENT 'Customer age in completed years as of the dataset reference date. Domain: Customer Profile. Classification: Yes. Derived from birth_date. May be NULL for organizations.';
ALTER TABLE customer_360 CHANGE city city STRING COMMENT 'City associated with the customer or registered vehicle. Domain: Location. Classification: Yes. Use with province, latitude, and longitude.';
ALTER TABLE customer_360 CHANGE province province STRING COMMENT 'Province associated with the customer or registered vehicle. Domain: Location. Classification: Yes. Useful for regional analysis and campaign targeting.';
ALTER TABLE customer_360 CHANGE latitude latitude DOUBLE COMMENT 'Latitude coordinate of the customer or vehicle location. Domain: Location. Classification: Yes. Approximate demo coordinate. Use for mapping and spatial grouping.';
ALTER TABLE customer_360 CHANGE longitude longitude DOUBLE COMMENT 'Longitude coordinate of the customer or vehicle location. Domain: Location. Classification: Yes. Approximate demo coordinate. Use for mapping and spatial grouping.';
ALTER TABLE customer_360 CHANGE vehicle_id vehicle_id STRING COMMENT 'Unique synthetic identifier for a registered vehicle. Domain: Vehicle. Classification: No. Example: VEH000001.';
ALTER TABLE customer_360 CHANGE vehicle_type vehicle_type STRING COMMENT 'Category of the registered vehicle. Domain: Vehicle. Classification: No. Examples: Passenger Car, Motorcycle, Bus, Truck.';
ALTER TABLE customer_360 CHANGE vehicle_brand vehicle_brand STRING COMMENT 'Brand or manufacturer of the vehicle. Domain: Vehicle. Classification: No. Examples: Toyota, Honda, Suzuki.';
ALTER TABLE customer_360 CHANGE vehicle_year vehicle_year INT COMMENT 'Manufacturing year of the vehicle. Domain: Vehicle. Classification: No. Used to derive vehicle_age.';
ALTER TABLE customer_360 CHANGE vehicle_age vehicle_age INT COMMENT 'Age of the vehicle in years. Domain: Vehicle. Classification: No. Derived from current year minus vehicle_year.';
ALTER TABLE customer_360 CHANGE plate_region plate_region STRING COMMENT 'Regional prefix of the vehicle registration plate. Domain: Vehicle. Classification: No. Example: B, D, F.';
ALTER TABLE customer_360 CHANGE organization_name organization_name STRING COMMENT 'Organization name when customer_type is Organization. Domain: Customer Profile. Classification: Yes. NULL for individual customers.';
ALTER TABLE customer_360 CHANGE transaction_id transaction_id STRING COMMENT 'Unique synthetic identifier for the latest Sumbangan Wajib transaction. Domain: Transaction. Classification: No. Example: TRX000001.';
ALTER TABLE customer_360 CHANGE transaction_date transaction_date DATE COMMENT 'Date of the latest recorded Sumbangan Wajib transaction. Domain: Transaction. Classification: No. Use for recency and trend analysis.';
ALTER TABLE customer_360 CHANGE last_payment_date last_payment_date DATE COMMENT 'Most recent payment date recorded for the customer. Domain: Transaction. Classification: No. Use to identify overdue or inactive customers.';
ALTER TABLE customer_360 CHANGE payment_status payment_status STRING COMMENT 'Current payment status of the customer. Domain: Transaction. Classification: No. Typical values: Paid, Overdue, Pending.';
ALTER TABLE customer_360 CHANGE sw_amount sw_amount DECIMAL(18,2) COMMENT 'Amount of Sumbangan Wajib associated with the latest transaction. Domain: Finance. Classification: Confidential. Currency: Indonesian Rupiah.';
ALTER TABLE customer_360 CHANGE penalty_amount penalty_amount DECIMAL(18,2) COMMENT 'Penalty or late fee amount associated with the transaction. Domain: Finance. Classification: Confidential. Zero indicates no penalty.';
ALTER TABLE customer_360 CHANGE claim_id claim_id STRING COMMENT 'Synthetic identifier of a representative or latest claim record. Domain: Claim. Classification: Confidential. May be NULL when no claim exists.';
ALTER TABLE customer_360 CHANGE claim_count claim_count INT COMMENT 'Number of claims associated with the customer. Domain: Claim. Classification: Confidential. Use for risk and customer profile analysis.';
ALTER TABLE customer_360 CHANGE claim_amount claim_amount DECIMAL(18,2) COMMENT 'Total or representative claim amount associated with the customer. Domain: Claim. Classification: Confidential. Currency: Indonesian Rupiah.';
ALTER TABLE customer_360 CHANGE journal_amount journal_amount DECIMAL(18,2) COMMENT 'Financial journal amount associated with the transaction. Domain: Finance. Classification: Confidential. Typically used for reconciliation.';
ALTER TABLE customer_360 CHANGE inflation_rate inflation_rate DOUBLE COMMENT 'Inflation rate relevant to the transaction period or region. Domain: External Context. Classification: No. Stored as percentage points, for example 2.15 means 2.15 percent.';
ALTER TABLE customer_360 CHANGE weather_condition weather_condition STRING COMMENT 'Weather condition associated with the transaction or regional context. Domain: External Context. Classification: No. Examples: Sunny, Rainy, Cloudy.';
ALTER TABLE customer_360 CHANGE economic_index economic_index DOUBLE COMMENT 'Synthetic economic index representing macroeconomic conditions. Domain: External Context. Classification: No. Higher values indicate stronger economic conditions in this demo.';
ALTER TABLE customer_360 CHANGE segment segment STRING COMMENT 'Current customer segment assigned by segmentation logic. Domain: Analytics. Classification: Confidential. Examples: Premium, Growth, Standard, At Risk.';
ALTER TABLE customer_360 CHANGE renewal_probability renewal_probability DOUBLE COMMENT 'Predicted probability that the customer will renew or pay in the next period. Domain: Analytics. Classification: Confidential. Range 0 to 1. Higher values indicate higher renewal likelihood.';
ALTER TABLE customer_360 CHANGE cross_sell_score cross_sell_score DOUBLE COMMENT 'Predicted suitability score for cross-sell or upsell campaigns. Domain: Analytics. Classification: Confidential. Range 0 to 1. Higher values indicate stronger campaign potential.';
ALTER TABLE customer_360 CHANGE retention_score retention_score DOUBLE COMMENT 'Estimated likelihood that the customer can be retained through engagement. Domain: Analytics. Classification: Confidential. Range 0 to 1. Higher values indicate stronger retention potential.';
ALTER TABLE customer_360 CHANGE churn_risk churn_risk DOUBLE COMMENT 'Predicted risk that the customer will become inactive or fail to renew. Domain: Analytics. Classification: Confidential. Range 0 to 1. Higher values indicate higher churn risk.';
ALTER TABLE customer_360 CHANGE preferred_channel preferred_channel STRING COMMENT 'Preferred communication channel for engagement. Domain: Campaign. Classification: Yes. Examples: WhatsApp, SMS, Email, Call.';
ALTER TABLE customer_360 CHANGE last_campaign last_campaign STRING COMMENT 'Most recent campaign associated with the customer. Domain: Campaign. Classification: Confidential. Example: Retention 2026, MTPL Cross-sell, No Campaign.';
ALTER TABLE customer_360 CHANGE campaign_response campaign_response STRING COMMENT 'Customer response to the most recent campaign. Domain: Campaign. Classification: Confidential. Examples: Responded, Converted, No Response, Not Contacted.';
ALTER TABLE customer_360 CHANGE predicted_revenue predicted_revenue DECIMAL(18,2) COMMENT 'Estimated future revenue contribution from the customer. Domain: Analytics. Classification: Confidential. Currency: Indonesian Rupiah. Model-generated estimate.';
ALTER TABLE customer_360 CHANGE data_quality_score data_quality_score DOUBLE COMMENT 'Overall quality score for the customer record. Domain: Data Governance. Classification: No. Range 0 to 1. Higher values indicate more complete and reliable data.';